-- Target: SQL Server 2019 (15.x). Same query as the sql2022 pack: every object it reads exists on 2019.
-- Target permissions: on 2019 the DMVs and DMFs it reads need VIEW SERVER STATE (2022 split this into narrower ones).
-- Memory dumps generated by the instance (sys.dm_server_memory_dumps).
-- Read-only: a SELECT over the DMV; the files are not opened.
-- creationTime in the server's local time zone (the datetimeoffset offset is discarded).
SELECT TOP (50)
    CAST(md.filename AS NVARCHAR(512)) AS fileName,
    CAST(md.creation_time AS DATETIME2) AS creationTime,
    CAST(md.size_in_bytes / 1048576.0 AS DECIMAL(18,2)) AS sizeMb
FROM sys.dm_server_memory_dumps AS md
ORDER BY md.creation_time DESC, md.filename
